    _fields_ = [("data", ctypes.POINTER(gsl_complex)),
                ("size1", ctypes.c_size_t),
                ("size2", ctypes.c_size_t),
                ("tda", ctypes.c_size_t)]

def create_gsl_matrix_complex(np_array):
    if not isinstance(np_array, np.ndarray):
        raise ValueError("Input must be a NumPy array")
    if np_array.ndim != 2:
        raise ValueError("Array must be 2-dimensional")
    if np_array.dtype != np.complex128:
        raise ValueError("Array must be of complex128 type")
    if not np_array.flags.c_contiguous:
