class GSLWorkspaceManager:
    def __init__(self):
        self.libgslcblas = ctypes.CDLL("/usr/local/gsl/lib/libgslcblas.so", mode=ctypes.RTLD_GLOBAL)
        self.gsl = ctypes.CDLL("/usr/local/gsl/lib/libgsl.so")

        self.gsl.gsl_integration_workspace_alloc.argtypes = [ctypes.c_size_t]
        self.gsl.gsl_integration_workspace_alloc.restype = ctypes.c_void_p

        self.gsl.gsl_integration_workspace_free.argtypes = [ctypes.c_void_p]
        self.gsl.gsl_integration_workspace_free.restype = None

    def allocate_workspace(self, n):
        if not isinstance(n, int) or n <= 0:
            raise ValueError("Input n must be a positive integer")

        workspace = self.gsl.gsl_integration_workspace_alloc(n)
        if not workspace:
            raise RuntimeError("Failed to allocate GSL workspace")
        return workspace

    def free_workspace(self, workspace):
        if workspace is None:
            raise ValueError("Invalid workspace pointer")
        self.gsl.gsl_integration_workspace_free(workspace)

